window.RP_SESSION={"id":"S-ecff2fc06119","messages":[{"id":"RP-0113762","time":"2026-04-15T23:48:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"주점! 오늘은 좀 쉬어야지. 했던 게 길게 이어져서는···. 결국 친해진 친구들과 함께 레아는 주점 안에 위치했다.\n\n다양한 종의 인물들이 뒤얽히고 웃고 마시고···. 구석의 주점은 엉망진창이 된 터지만. 주점 주인은 돈이라며 말갛게 웃고 있을 뿐이다.","characters":["P-92b9d287989c"]},{"id":"RP-0113763","time":"2026-04-15T23:48:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"··· 뭔갈 까먹은 것 같은데.","characters":["P-92b9d287989c"]},{"id":"RP-0113764","time":"2026-04-15T23:48:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"!지능","characters":["P-92b9d287989c"]},{"id":"RP-0113765","time":"2026-04-15T23:48:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레아'의 지능 판정 :\n[1] + [0] = [1]\n결과 : 비극, 이 또한 당신의 운명입니다.","characters":[]},{"id":"RP-0113766","time":"2026-04-15T23:49:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"뭐더라.","characters":["P-92b9d287989c"]},{"id":"RP-0113767","time":"2026-04-15T23:49:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"뭐···. 새벽에 뭐 할 게 있었는데.","characters":["P-92b9d287989c"]},{"id":"RP-0113768","time":"2026-04-15T23:49:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"방긋! 그러면 어떠하리! 친구들과 술이 있는데!","characters":["P-92b9d287989c"]},{"id":"RP-0113769","time":"2026-04-15T23:50:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"레아가 맥주잔을 들어 벌컥벌컥, 한 숨에 맥주를 들이키니. 레아의 친구들은 그것이 응원할 것이라는 둥. 박수를 치기 시작했다.","characters":["P-92b9d287989c"]},{"id":"RP-0113770","time":"2026-04-15T23:50:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"덜컥. 끼익. 문이 열리는 소리.","characters":["P-7ba611cf90be"]},{"id":"RP-0113771","time":"2026-04-15T23:50:00+09:00","room":"RP","name":"샤를로타 롯테","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"!민첩","characters":["P-4f32affb54c8"]},{"id":"RP-0113772","time":"2026-04-15T23:50:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'샤를로타 롯테'의 민첩 판정 :\n[10] + [2] = [12]\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-0113773","time":"2026-04-15T23:50:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"저벅.저벅. 땡그랑.\n\n\"주인장. 맥주 한 잔.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113774","time":"2026-04-15T23:51:00+09:00","room":"RP","name":"샤를로타 롯테","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"롯테는 오늘도 완벽히 은밀기동 중이다.","characters":["P-4f32affb54c8"]},{"id":"RP-0113775","time":"2026-04-15T23:51:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 아하하, 세인트, 이름이 그리 고급져서야 되겠나! ”\n\n하며 턱, 한 남자의 어깨에 손 얹고.","characters":["P-92b9d287989c"]},{"id":"RP-0113776","time":"2026-04-15T23:51:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 이렇게 방탕하게 놀면서 무얼 고급진 이름을 가지겠다고! ”","characters":["P-92b9d287989c"]},{"id":"RP-0113777","time":"2026-04-15T23:51:00+09:00","room":"RP","name":"샤를로타 롯테","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"엿듣기는 못참지.","characters":["P-4f32affb54c8"]},{"id":"RP-0113778","time":"2026-04-15T23:51:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"?\"\n\n맥주 한잔을 받아들고는 어디서 많이 들은 목소리에 고개를 돌아본다.","characters":["P-7ba611cf90be"]},{"id":"RP-0113779","time":"2026-04-15T23:51:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"오호라.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113780","time":"2026-04-15T23:52:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"맥주를 홀짝거리고는 잠시 지켜본다.","characters":["P-7ba611cf90be"]},{"id":"RP-0113781","time":"2026-04-15T23:52:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"세인트의 머리에 꿀밤 먹이듯 꾹 누르기 시작했다. 레아가 허리를 숙이자 세인트라는 남자도 가만히 고개를 숙이는 것이었다.","characters":["P-92b9d287989c"]},{"id":"RP-0113782","time":"2026-04-15T23:53:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 저번 술 내기는 내가 이겼으니! 이번에는 자네가 내게! ”\n\n호탕하게 웃어재끼곤.","characters":["P-92b9d287989c"]},{"id":"RP-0113783","time":"2026-04-15T23:53:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"!매력","characters":["P-92b9d287989c"]},{"id":"RP-0113784","time":"2026-04-15T23:53:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레아'의 매력 판정 :\n[9] + [0] = [9]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-0113785","time":"2026-04-15T23:54:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"그렇게 웃고 있자니. 세인트라는 사내는 신체 접촉에 당황하며 볼을 붉히는 것이었다.\n\n당연히 레아는 그것을 몰랐을테고···.","characters":["P-92b9d287989c"]},{"id":"RP-0113786","time":"2026-04-15T23:54:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"이모티콘","characters":["P-7ba611cf90be"]},{"id":"RP-0113787","time":"2026-04-15T23:54:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"가볍게 세인트를 풀어주고, 주인장에게로 방긋 웃으며 다가가서는.","characters":["P-92b9d287989c"]},{"id":"RP-0113788","time":"2026-04-15T23:55:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 주인장! 맥주 세잔, 저 자식한테 달아놓ㄱ···. ”","characters":["P-92b9d287989c"]},{"id":"RP-0113789","time":"2026-04-15T23:55:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"이모티콘","characters":["P-92b9d287989c"]},{"id":"RP-0113790","time":"2026-04-15T23:55:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"세 잔이면 내 것도 사주게나.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113791","time":"2026-04-15T23:55:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"토르번 바라보고 눈을 꿈뻑거립니다.","characters":["P-92b9d287989c"]},{"id":"RP-0113792","time":"2026-04-15T23:55:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"킥킥 거리며 웃습니다.","characters":["P-7ba611cf90be"]},{"id":"RP-0113793","time":"2026-04-15T23:55:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"!지능","characters":["P-92b9d287989c"]},{"id":"RP-0113794","time":"2026-04-15T23:55:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레아'의 지능 판정 :\n[1] + [0] = [1]\n결과 : 비극, 이 또한 당신의 운명입니다.","characters":[]},{"id":"RP-0113795","time":"2026-04-15T23:55:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"와 이거","characters":["P-92b9d287989c"]},{"id":"RP-0113796","time":"2026-04-15T23:55:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"?","characters":["P-7ba611cf90be"]},{"id":"RP-0113797","time":"2026-04-15T23:55:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"얘","characters":["P-92b9d287989c"]},{"id":"RP-0113798","time":"2026-04-15T23:55:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"예사롭지 ㅋㅋ 않은데?","characters":["P-92b9d287989c"]},{"id":"RP-0113799","time":"2026-04-15T23:55:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"얘 와","characters":["P-92b9d287989c"]},{"id":"RP-0113800","time":"2026-04-15T23:55:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"와,,, 우와 이거","characters":["P-92b9d287989c"]},{"id":"RP-0113801","time":"2026-04-15T23:55:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"ㅋㅋ","characters":["P-92b9d287989c"]},{"id":"RP-0113802","time":"2026-04-15T23:56:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"오늘 훈련이 있었는데.","characters":["P-92b9d287989c"]},{"id":"RP-0113803","time":"2026-04-15T23:56:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"까맣게 까먹은지 오래.","characters":["P-92b9d287989c"]},{"id":"RP-0113804","time":"2026-04-15T23:56:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113805","time":"2026-04-15T23:56:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"” 그럼요! 스승님이라면 몇잔이라도 사드리겠슴다! ”\n\n파하, 신나게 웃고선.","characters":["P-92b9d287989c"]},{"id":"RP-0113806","time":"2026-04-15T23:56:00+09:00","room":"RP","name":"페트라","profile":"페트라","identity":"unresolved","type":"dialogue","body":"이모티콘","characters":[]},{"id":"RP-0113807","time":"2026-04-15T23:56:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"··· 저 먼, 맥주잔 잔뜩 쌓인 곳 가르킵니다.","characters":["P-92b9d287989c"]},{"id":"RP-0113808","time":"2026-04-15T23:56:00+09:00","room":"RP","name":"샤를로타 롯테","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"이모티콘","characters":["P-4f32affb54c8"]},{"id":"RP-0113809","time":"2026-04-15T23:57:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 애들이랑 내기 하고 있었는데요, 스승님도 술 좀 잘하심까? ”","characters":["P-92b9d287989c"]},{"id":"RP-0113810","time":"2026-04-15T23:57:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...많이도 마셨군?\"\n\n일단 자신이 산 맥주 호로록","characters":["P-7ba611cf90be"]},{"id":"RP-0113811","time":"2026-04-15T23:57:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"술? 술이 없는데 이 자리에.\"\n\n맥주따위는 술도 아니라는 듯","characters":["P-7ba611cf90be"]},{"id":"RP-0113812","time":"2026-04-15T23:58:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 제가 아마 잘 마실검다. 삼일 밤낮으로 마신 적도 있으니까! ”\n\n큭큭, 웃고서는 나온 맥주잔 잡아듭니다.","characters":["P-92b9d287989c"]},{"id":"RP-0113813","time":"2026-04-15T23:58:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 여기 맥주는 은근 센데요. 애들 돈으로는 비싼 술 가지고 내기도 어렵잖슴까. ”","characters":["P-92b9d287989c"]},{"id":"RP-0113814","time":"2026-04-15T23:58:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"unresolved","type":"dialogue","body":"술을 잘마신다고?","characters":[]},{"id":"RP-0113815","time":"2026-04-15T23:58:00+09:00","room":"RP","name":"Maria Anaïs Ésther","profile":"Maria Anaïs Ésther","identity":"unresolved","type":"dialogue","body":"덤벼","characters":[]},{"id":"RP-0113816","time":"2026-04-15T23:58:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"오늘은 아직 하루 밖에 안 마셨으니 다행이군.\"\n\n\"훈련장에 스승을 사흘이나 혼자 세워 둘 수는 없으니.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113817","time":"2026-04-15T23:59:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"아니레아는잘마셔컨셉이","characters":["P-92b9d287989c"]},{"id":"RP-0113818","time":"2026-04-15T23:59:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"얘그래도북부인이잖아ㅠㅜ","characters":["P-92b9d287989c"]},{"id":"RP-0113819","time":"2026-04-15T23:59:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ ······ 넹? ”","characters":["P-92b9d287989c"]},{"id":"RP-0113820","time":"2026-04-15T23:59:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"이모티콘","characters":["P-92b9d287989c"]},{"id":"RP-0113821","time":"2026-04-15T23:59:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"이모티콘","characters":["P-92b9d287989c"]},{"id":"RP-0113822","time":"2026-04-15T23:59:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...오늘도 훈련하는 거 아니였나?\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113823","time":"2026-04-15T23:59:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"이모티콘","characters":["P-92b9d287989c"]},{"id":"RP-0113824","time":"2026-04-16T00:00:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 그그, 쵸, 그쵸. 그럼요! ”","characters":["P-92b9d287989c"]},{"id":"RP-0113825","time":"2026-04-16T00:00:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"나온 맥주잔 조용히 옆으로 밀어냅니다.","characters":["P-92b9d287989c"]},{"id":"RP-0113826","time":"2026-04-16T00:00:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 당~ 연히! 해야죠. ”","characters":["P-92b9d287989c"]},{"id":"RP-0113827","time":"2026-04-16T00:00:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"난 또. 검 휘두르는 법도 안 가르쳐 주는 스승보다는 맥주가 훨씬 좋은 줄 알았지.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113828","time":"2026-04-16T00:00:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"**!!!! 속으로 욕지거리 중얼입니다. 쒸, 쒸에에엣.","characters":["P-92b9d287989c"]},{"id":"RP-0113829","time":"2026-04-16T00:01:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 그럴리가요! 스승님이 젤 좋슴다, 다른 사람도 아니고, 맥, 맥주가 더 좋을리가요! ”","characters":["P-92b9d287989c"]},{"id":"RP-0113830","time":"2026-04-16T00:02:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"그럼그럼.\"\n\n키득키득.\n\n\"농일세. 술 좀 마시는 걸로 뭐라할 생각 없다네. 어차피 기다리는 것도 내 훈련이나 했으니.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113831","time":"2026-04-16T00:02:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ ··· 금방 정리하고 나오겠슴다. 애들, 애들이 좀 많아서. ”\n\n레아가 당황했습니다. 그런 모습 보기 흔치 않은지. 레아의 친구들은 가만히 레아를 살펴봅니다.","characters":["P-92b9d287989c"]},{"id":"RP-0113832","time":"2026-04-16T00:03:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"총총총, 다른 친구들에게도 가서 똑같이 보이지도 않는 꼬리 흔들어대며 인사 전합니다. 가끔은 꼭 끌어안기도 하고, 머리를 툭 치기도 하고.","characters":["P-92b9d287989c"]},{"id":"RP-0113833","time":"2026-04-16T00:04:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"그리고 저 구석에 걸쳐둔 제 검집 잡고선.","characters":["P-92b9d287989c"]},{"id":"RP-0113834","time":"2026-04-16T00:04:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"” 갈까요? “\n\n하며 토르번 바라봅니다.","characters":["P-92b9d287989c"]},{"id":"RP-0113835","time":"2026-04-16T00:05:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"아니. 오늘은 좀 쉬지. 술 마시고 어제같은 훈련이라니, 몸이 성치 않을 걸.\"\n\n맥주잔을 레아에게 내밉니다.","characters":["P-7ba611cf90be"]},{"id":"RP-0113836","time":"2026-04-16T00:07:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"엇···. 아싸! 내심 신난 듯 빵긋 웃고선. 맥주잔 잡고 짠.","characters":["P-92b9d287989c"]},{"id":"RP-0113837","time":"2026-04-16T00:08:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 저 길드에서는 스승님이 첫 친구임다. ”","characters":["P-92b9d287989c"]},{"id":"RP-0113838","time":"2026-04-16T00:08:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...오호라. 그거 영광이군 그래.\"\n\n키득키득 웃으며 잔을 맞댄 후 들이킵니다.","characters":["P-7ba611cf90be"]},{"id":"RP-0113839","time":"2026-04-16T00:09:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"그렇지만 술은 멀리하는 게 좋다네. 북부인은 전부 미인이지만 스물일곱이 넘어가면 술 때문에 팍 늙어버린다는 말이 있지.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113840","time":"2026-04-16T00:09:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"제대로 놀 줄 아는 날라리···.일까요. 제 옷에 살짝 떨어지는 것 개의치 않고 마십니다.","characters":["P-92b9d287989c"]},{"id":"RP-0113841","time":"2026-04-16T00:09:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"토르번의 말에 호탕하게 웃어보입니다.","characters":["P-92b9d287989c"]},{"id":"RP-0113842","time":"2026-04-16T00:10:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 그랬음 저희 가족은 이미 관에 있을걸요! 아하하, 저도 그럼 갓 성인 되어서 진작에 라운데라님을 뵙고 있을텐데요! “","characters":["P-92b9d287989c"]},{"id":"RP-0113843","time":"2026-04-16T00:11:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"푸하하 당연히 간은 문제 없지. 북부인인 걸. 술 살 때문에 얼굴이 확 못생겨질 걸.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113844","time":"2026-04-16T00:12:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 제가 그렇게 쉽게 못생겨질 얼굴은 아닐걸요? ”\n\n제 얼굴 가르킵니다.","characters":["P-92b9d287989c"]},{"id":"RP-0113845","time":"2026-04-16T00:12:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 반짝거려서 눈을 놓치지 못할검다. ”\n\n케케.","characters":["P-92b9d287989c"]},{"id":"RP-0113846","time":"2026-04-16T00:12:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"갓 맹꽁이 벗어난 주제에 말은 잘하는군.\"\n\n키득키득\n\n\"그러다 한 방에 훅 가는 거라네.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113847","time":"2026-04-16T00:13:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ ··· 에헹? 저 맹꽁이라기엔 술 잘 마시는뎃, 요. “\n\n중간중간 뭉개지며 말하던 것, 혀 깨물자 고쳐집니다.","characters":["P-92b9d287989c"]},{"id":"RP-0113848","time":"2026-04-16T00:13:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"” 아야. “\n\n혀 내밀고 있다가.","characters":["P-92b9d287989c"]},{"id":"RP-0113849","time":"2026-04-16T00:14:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"얼씨구. 맹랑하기까지.\"\n\n\"그 몸으로 훈련 나갈 생각을 잘도 했군.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113850","time":"2026-04-16T00:15:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 검술은 잘만 해요, 부모님이 가르치신 게 있어가지고. ”\n\n맥주 다시 들이킵니다. 알콜로 소독한다, 같은 실 없는 소리 내뱉으며.","characters":["P-92b9d287989c"]},{"id":"RP-0113851","time":"2026-04-16T00:15:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"” 이래서 매력적이라고들 하는 게 아니겠어요? 맹랑한 게 보기 좋은 겁니다. “\n\n제 말 자기가 인정한다는 듯.","characters":["P-92b9d287989c"]},{"id":"RP-0113852","time":"2026-04-16T00:17:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"unresolved","type":"dialogue","body":"엘프는 술마셔도 안늙는데","characters":[]},{"id":"RP-0113853","time":"2026-04-16T00:17:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"자신감 있는 모습이야 보기 좋다네.\"\n\n다 마신 맥주잔을 텅. 내려놓고는.\n\n\"어제 그렇게 혼나놓고도 자신감이 넘치는 걸.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113854","time":"2026-04-16T00:17:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 앗. ”","characters":["P-92b9d287989c"]},{"id":"RP-0113855","time":"2026-04-16T00:17:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"멈칫.","characters":["P-92b9d287989c"]},{"id":"RP-0113856","time":"2026-04-16T00:18:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ ·········. ”\n\n뜨끔했는지 고개 슬쩍 돌립니다.","characters":["P-92b9d287989c"]},{"id":"RP-0113857","time":"2026-04-16T00:18:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"큭큭. 눈이 찡그러질 정도로 웃습니다.","characters":["P-7ba611cf90be"]},{"id":"RP-0113858","time":"2026-04-16T00:18:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"툭, 지나가는 세인트에게 화풀이하듯 발 겁니다.","characters":["P-92b9d287989c"]},{"id":"RP-0113859","time":"2026-04-16T00:19:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"세인트가 당황해서 바라보니, 빵긋 웃고서는 손 휘적휘적.","characters":["P-92b9d287989c"]},{"id":"RP-0113860","time":"2026-04-16T00:20:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"얼씨구? 친구한테 화풀이 해서 쓰나. 나도 친구라더니 곧 내 발도 걸겠군.\"\n\n\"주인장 여기 맥주 두 잔 더 주게. 팔켄하인 이름으로 달아놓고.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113861","time":"2026-04-16T00:20:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"” 아, 거, 스승님은 좀 다르죠, 쟤는···. 이상하게 눈빛이 기분 나빠. “\n\n짖궃게 웃고선. 다시 뒤돌아 토르번 바라봅니다.","characters":["P-92b9d287989c"]},{"id":"RP-0113862","time":"2026-04-16T00:20:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"” 사주시는 거예요? 아~ 싸! “","characters":["P-92b9d287989c"]},{"id":"RP-0113863","time":"2026-04-16T00:21:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"기분이 나쁘다라... 음... 내 생각에는...\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113864","time":"2026-04-16T00:21:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"흠...\"\n\n잔을 받아들고는 레아를 빤히.","characters":["P-7ba611cf90be"]},{"id":"RP-0113865","time":"2026-04-16T00:22:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 넹? ”\n\n··· 마냥 웃습니다.","characters":["P-92b9d287989c"]},{"id":"RP-0113866","time":"2026-04-16T00:22:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-92b9d287989c"]},{"id":"RP-0113867","time":"2026-04-16T00:22:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"아닐세. 아니야. 모르는 게 더 재밌겠군.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113868","time":"2026-04-16T00:23:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 아, 그거요? ”","characters":["P-92b9d287989c"]},{"id":"RP-0113869","time":"2026-04-16T00:23:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"토르번 바라보다가, 파하하! 하며 웃음 내뱉습니다.","characters":["P-92b9d287989c"]},{"id":"RP-0113870","time":"2026-04-16T00:23:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 모를 리가! 재미있으니 가만 두는 거죠. 그런 사람 한 둘입니까? ”\n\n토르번 훑어보다가.\n\n“ 흠, 스승님도 꽤 있으시겠는데요. ”","characters":["P-92b9d287989c"]},{"id":"RP-0113871","time":"2026-04-16T00:25:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"과장된 투로 경악하며.\n\n\"오 세상에 라운데라시여. 이 악랄한 처자를 어쩌면 좋습니까.\"\n\n그리고는 아무일도 없다는 듯 맥주를 꿀꺽.\n\n\"내가 있긴 뭘.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113872","time":"2026-04-16T00:26:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 글쎄요. 아까부터 인기척이랑 시선이 느껴지는 것 봐선. 많을 것 같은데~ ”\n\n오오오, 하며 쿡, 토르번 옆구리 팔꿈치로 가볍게 찌릅니다.","characters":["P-92b9d287989c"]},{"id":"RP-0113873","time":"2026-04-16T00:26:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 저야, 뭐···. 어차피 제가 안 좋아하니 그만 아니겠어요? ”","characters":["P-92b9d287989c"]},{"id":"RP-0113874","time":"2026-04-16T00:26:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 지가 좋아하겠다는데, 뭘, ”\n\n킥킥.","characters":["P-92b9d287989c"]},{"id":"RP-0113875","time":"2026-04-16T00:27:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"옆구리 공격에 어어. 이 건방진 것 좀 보게라는 눈빛으로 내려다봅니다.\n\n\"이성 관계는 확실히 하는 게 좋아. 괜히 귀찮아진다네.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113876","time":"2026-04-16T00:28:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 전 괜찮습니다, 혹시 몰라. 저러다 운명의 상대가 나타날지도! “","characters":["P-92b9d287989c"]},{"id":"RP-0113877","time":"2026-04-16T00:29:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"드라마틱하게 제 손등 이마에 얹고서.","characters":["P-92b9d287989c"]},{"id":"RP-0113878","time":"2026-04-16T00:30:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"아주 그냥 바람둥이가 따로없군. 기가 차서는... 열심히 해보게.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113879","time":"2026-04-16T00:31:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 아 물론 그 운명의 상대가 저는 아니면 좋겠고요. “\n\n재빠르게 말 내뱉습니다, 그리고, 손등 툭 내리고. 맥주잔 잡습니다.","characters":["P-92b9d287989c"]},{"id":"RP-0113880","time":"2026-04-16T00:31:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 오래 같이할 파트너가 필요한 거지, 가볍게 만날 거면 연애를···. 왜 하남. ”","characters":["P-92b9d287989c"]},{"id":"RP-0113881","time":"2026-04-16T00:31:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"맥주잔 들어 벌컥.","characters":["P-92b9d287989c"]},{"id":"RP-0113882","time":"2026-04-16T00:32:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"제법 건실한 생각을 하는군. 그 부분은 동감일세. 물론 매일같이 방탕하게 놀아서는 파트너가 질색하며 도망치겠지만.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113883","time":"2026-04-16T00:35:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 앗··· 그, 그건 고칠건데요. 좋아하는 사람이 생기게 되면 당연히 낯도 좀 가리고, 좀 살랑거리고···. ”","characters":["P-92b9d287989c"]},{"id":"RP-0113884","time":"2026-04-16T00:35:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ ··· 와, 좀 싫은데. ”","characters":["P-92b9d287989c"]},{"id":"RP-0113885","time":"2026-04-16T00:37:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"함께한 날이 길지는 않지만... 상상이 안 가는데.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113886","time":"2026-04-16T00:37:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"누군가가 좋다면 꾸밈없이 하게나. 그게 가장 매력적일테니.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113887","time":"2026-04-16T00:38:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ ······ 에~ 엥? 매력 없을 것 같은데요. “","characters":["P-92b9d287989c"]},{"id":"RP-0113888","time":"2026-04-16T00:38:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"” 자고로, 어···. 왈츠도 좀 추고. “","characters":["P-92b9d287989c"]},{"id":"RP-0113889","time":"2026-04-16T00:38:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"방금은 맹랑한 게 매력이라며?\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113890","time":"2026-04-16T00:41:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ ··· 길거리에서의 매력과 연애의 매력은. ”","characters":["P-92b9d287989c"]},{"id":"RP-0113891","time":"2026-04-16T00:41:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 좀, 다르지··· 않나요? ”","characters":["P-92b9d287989c"]},{"id":"RP-0113892","time":"2026-04-16T00:41:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"무경험자.","characters":["P-92b9d287989c"]},{"id":"RP-0113893","time":"2026-04-16T00:43:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"어떻게 쓰느냐에 따라 다른거지.\"\n\n\"고상한 연애가 하고 싶다면, 왈츠도 추고 와인도 마시고, 수줍게 마차에서 내리고.\"\n\n\"다만 인생의 파트너를 만나려면 나를 보여주는 게 가장 좋은 방법 아니겠나.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113894","time":"2026-04-16T00:47:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 아, 복잡하네. 그런 사람 나오면 고민해보겠슴다···. 그냥 술만 강한 사람이면 괜찮을 것 같은데. ”\n\n쳇.","characters":["P-92b9d287989c"]},{"id":"RP-0113895","time":"2026-04-16T00:48:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 뭐, 저기선 고급져야 한다, 여기선 낯 가려야 한다. 귀족들은 너무 바쁘시겠네. ”","characters":["P-92b9d287989c"]},{"id":"RP-0113896","time":"2026-04-16T00:50:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"unresolved","type":"dialogue","body":"엘프랑 사겨","characters":[]},{"id":"RP-0113897","time":"2026-04-16T00:50:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"귀족들은 바쁘지. 자리라는 게 태생적인 허울만 존재하는 것이 아니라네. 백조의 발길질은 우아하지 않은 것 처럼. 머리통 빠그라지는 뒷 이야기들이 더 많은 걸세.\"\n\n또다시 다 마신 맥주를 내려놓는다.\n\n\"뭐... 재미없는 얘기는 고사하고. 친구들 중에 괜찮은 녀석은 있던가?\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113898","time":"2026-04-16T00:51:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"남자엘프 활동성 많은 사람이 있나","characters":["P-92b9d287989c"]},{"id":"RP-0113899","time":"2026-04-16T00:51:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"없지 ㅋㅋ","characters":["P-7ba611cf90be"]},{"id":"RP-0113900","time":"2026-04-16T00:52:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 뭐, 스승님께 소개시켜드릴 애요? “\n\n곰곰히···.\n\n” 주변에 여자애는 없는데. 프릴, 샤를, 엘리아? 또 누구 있더라. 셋 다 그닥···. 스승님은 좀, 고급지셔서. ”","characters":["P-92b9d287989c"]},{"id":"RP-0113901","time":"2026-04-16T00:52:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"외모 가르키듯 제 얼굴 손바닥으로 쓱 위아래로 움직입니다.","characters":["P-92b9d287989c"]},{"id":"RP-0113902","time":"2026-04-16T00:53:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"뭐. 아니아니. 나는 맹꽁이들은 관심없다네.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113903","time":"2026-04-16T00:53:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"자네 눈에 차던 남정네들 없냐는 거야.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113904","time":"2026-04-16T00:53:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"애들이 다 맹하긴 하지. 몸 가볍게 쭉 펴고.","characters":["P-92b9d287989c"]},{"id":"RP-0113905","time":"2026-04-16T00:54:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"” 글~ 쎄다. 그닥요. 다···. 와, 벌써 올라오는 것 같애. ”","characters":["P-92b9d287989c"]},{"id":"RP-0113906","time":"2026-04-16T00:54:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"헛구역질 나온다는 얼굴.","characters":["P-92b9d287989c"]},{"id":"RP-0113907","time":"2026-04-16T00:55:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"푸하하! 그렇게 싫은가?\"\n\n\"응당, 술집에서 인연을 찾는 게 택도 없는 소리긴 하지.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113908","time":"2026-04-16T00:58:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 우~ 와. 네. 싫어요. ”\n\n토르번 빤.","characters":["P-92b9d287989c"]},{"id":"RP-0113909","time":"2026-04-16T00:58:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 이상하다. 스승님이 여자가 없을 상은 아닌데. 길거리 돌아다니며 여자애들 쉽게 꼬시고 다니는···. ”","characters":["P-92b9d287989c"]},{"id":"RP-0113910","time":"2026-04-16T00:58:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 아, 길거리 아니겠다. ”","characters":["P-92b9d287989c"]},{"id":"RP-0113911","time":"2026-04-16T00:58:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 귀족스러운, 그런 파티? ”\n\n흠.","characters":["P-92b9d287989c"]},{"id":"RP-0113912","time":"2026-04-16T00:59:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...둘 다 내 취향은 아니군.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113913","time":"2026-04-16T00:59:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"저잣거리를 좋아하는 건 아니지만 귀족스러운 것이라면 나도 학을 뗀다네.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113914","time":"2026-04-16T01:00:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 엥? ”","characters":["P-92b9d287989c"]},{"id":"RP-0113915","time":"2026-04-16T01:00:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"파하학, 웃음 확 내뱉고, 시선 돌렸다가. 다시 토르번 당황스럽다는 듯 바라봅니다.","characters":["P-92b9d287989c"]},{"id":"RP-0113916","time":"2026-04-16T01:00:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 에엥? 스승님이? 와, 아닌데. 절대 아닌데. ”","characters":["P-92b9d287989c"]},{"id":"RP-0113917","time":"2026-04-16T01:02:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"어딜 보고 그렇게 생각하는지 모르겠군. 사교 모임은 영 체질이 아니야. 죄다 거짓말쟁이 능구렁이들만 모여서는...\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113918","time":"2026-04-16T01:02:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ ··· 이게, 사람이 태어난 얼굴 그대로 살아야 하는데요. ”","characters":["P-92b9d287989c"]},{"id":"RP-0113919","time":"2026-04-16T01:02:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"이모티콘","characters":["P-92b9d287989c"]},{"id":"RP-0113920","time":"2026-04-16T01:02:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 스승님은··· 별종이시네. ”","characters":["P-92b9d287989c"]},{"id":"RP-0113921","time":"2026-04-16T01:04:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...왜?\"\n\n\"어딜봐도 전장이나 모험이 어울릴 남자다운 얼굴인데.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113922","time":"2026-04-16T01:05:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 태어나서 절~ 대 바꿀 수 없는 게. “","characters":["P-92b9d287989c"]},{"id":"RP-0113923","time":"2026-04-16T01:05:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"” 첫째, 귀티. 둘째, 귀티. 셋째도 귀티거든요. “","characters":["P-92b9d287989c"]},{"id":"RP-0113924","time":"2026-04-16T01:05:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"” 근데···. 스승님한테는 번지르르하게 흐르시는데요. 금빛의 향이. ”\n\n쿡쿡.","characters":["P-92b9d287989c"]},{"id":"RP-0113925","time":"2026-04-16T01:07:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...으음... 칭찬은 아니군. 귀족과 기사는 그만둔지 오래라네.\"\n\n뒷머릴 긁적이다가.\n\n\"흉터가 하나 더 있어야 하려나.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113926","time":"2026-04-16T01:08:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 와. 그건 좀. ”","characters":["P-92b9d287989c"]},{"id":"RP-0113927","time":"2026-04-16T01:09:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"이모티콘","characters":["P-7ba611cf90be"]},{"id":"RP-0113928","time":"2026-04-16T01:09:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 좀···. 엥? 아냐. 멋있을 수도. ”\n\n토르번 왼톡부터, 입술까지 쓱 손가락으로.","characters":["P-92b9d287989c"]},{"id":"RP-0113929","time":"2026-04-16T01:09:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"unresolved","type":"dialogue","body":"이모티콘","characters":[]},{"id":"RP-0113930","time":"2026-04-16T01:09:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 이렇게 쭉 나면 멋은 나겠네요. “","characters":["P-92b9d287989c"]},{"id":"RP-0113931","time":"2026-04-16T01:10:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"움찔. 고개를 당겨 레아가 건드린 턱을 슬며시 피합니다.\n\n\"...그치? 흉터는 전사의 명예로운 증표라고.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113932","time":"2026-04-16T01:11:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 만들어 드릴까요. ”\n\n( ^ ^ )","characters":["P-92b9d287989c"]},{"id":"RP-0113933","time":"2026-04-16T01:12:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 이 정도 흉터는 면도칼로도 만들어지던데요. ”","characters":["P-92b9d287989c"]},{"id":"RP-0113934","time":"2026-04-16T01:12:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"명예가 뭔지 모르나...?\"\n\n\"그저 멋있어보이려고 죽죽 긋는 것에 전사의 훈장이 어딨어.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113935","time":"2026-04-16T01:15:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 아···. 명예는 지금 있으신 흉터로도 충분할 것 같슴다. ”\n\n빤···.","characters":["P-92b9d287989c"]},{"id":"RP-0113936","time":"2026-04-16T01:16:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"그렇기야 하지. 더 있어선 그저 산적처럼 보일 걸.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113937","time":"2026-04-16T01:16:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"헛짓거리 그만 생각하고 자네도 금방 훌륭한 전사로 만들어줘야지.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113938","time":"2026-04-16T01:17:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 저, 도요? ”\n\n음. 음···. 술, 술은 포기하기 어려운데.","characters":["P-92b9d287989c"]},{"id":"RP-0113939","time":"2026-04-16T01:19:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"그럴 생각으로 제자를 자원한 것 아닌가.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113940","time":"2026-04-16T01:21:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 아니, 맞죠! 맞, 습니다···. ”","characters":["P-92b9d287989c"]},{"id":"RP-0113941","time":"2026-04-16T01:24:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"정진해야지. 너도, 나도. 사랑노름은 그 다음 이야기일세.\"\n\n슬슬 자리에서 일어나 잠시 고민하다가.\n\n\"아닐 수도 있고.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113942","time":"2026-04-16T01:25:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"아닐 수도 있고오오? 흥미로운 것 포착한 것 마냥. 자리 다시 툭툭 두드립니다.","characters":["P-92b9d287989c"]},{"id":"RP-0113943","time":"2026-04-16T01:25:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 저 친구 많슴다, 연애 얘기도 그만큼 많고. ”\n\n켈켈.","characters":["P-92b9d287989c"]},{"id":"RP-0113944","time":"2026-04-16T01:27:00+09:00","room":"RP","name":"토르번 팔켄하인","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"으이구. 됐네. 됐어. 원 말을 함부로 못 꺼내겠군.\"\n\n의자를 정리하고, 자리를 뜨기 시작합니다.\n\n\"내일부터는 제대로 검 휘두르는 걸 가르쳐줄테니 푹 쉬게나.\"","characters":["P-7ba611cf90be"]},{"id":"RP-0113945","time":"2026-04-16T01:30:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 아, 아···. 재미 없으시네. ”\n\n에휴, 한숨 푹 내쉬고 인사합니다.\n\n“ 전 더 마시고 들어가겠슴다! ”","characters":["P-92b9d287989c"]},{"id":"RP-0113946","time":"2026-04-16T01:30:00+09:00","room":"RP","name":"레아 / 세인트·친구들","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"이모티콘","characters":["P-92b9d287989c"]}]};
